:where(a:hover){color:var(--o-palette-brand-700)}
::selection{background-color:var(--o-palette-brand-100)}
:where(:focus-visible){outline:2px solid var(--o-palette-brand-500);outline-offset:2px}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:0.01ms !important;animation-iteration-count:1 !important;transition-duration:0.01ms !important;scroll-behavior:auto !important}}

/* Preflight — theme sombre. */
:root[data-theme="dark"]{color-scheme:dark}
:root[data-theme="dark"] *,*::before,*::after{border-color:var(--o-palette-zinc-800)}
